mapper.select:
SELECT id, task_no, settle_date, member_id, file_type, version, status, retry_count, max_retry_count, last_message_id, last_send_time, last_consume_time, error_message, start_time, end_time, created_at, updated_at FROM settle_file_task
AND settle_date = #{settleDate}
AND status = #{status}
ORDER BY settle_date DESC, member_id ASC, file_type ASC, version ASC

SELECT id, task_no, settle_date, member_id, file_type, version, status, retry_count, max_retry_count, last_message_id, last_send_time, last_consume_time, error_message, start_time, end_time, created_at, updated_at FROM settle_file_task WHERE status IN ('INIT', 'SENT', 'FAILED')
AND settle_date = #{settleDate}
AND file_type = #{fileType}
ORDER BY settle_date ASC, member_id ASC, file_type ASC, version ASC

SELECT id, task_no, settle_date, member_id, file_type, version, status, retry_count, max_retry_count, last_message_id, last_send_time, last_consume_time, error_message, start_time, end_time, created_at, updated_at FROM settle_file_task WHERE settle_date = #{settleDate} AND file_type = #{fileType}
AND status = #{status}
AND status IN ('INIT', 'SENT', 'FAILED', 'SEND_FAILED')
ORDER BY settle_date ASC, member_id ASC, file_type ASC, version ASC

mapper.update:
UPDATE settle_file_task
SET status = 'FAILED',
    end_time = NOW(),
    retry_count = retry_count + 1,
    error_message = #{errorMessage}
WHERE task_no = #{taskNo}

UPDATE settle_file_task
SET status = 'SEND_FAILED',
    last_send_time = NOW(),
    error_message = #{errorMessage}
WHERE task_no = #{taskNo}
